    get activeCase(){return this.cases.find(c=>c.id===this.selectedId)||null}
    visibleCases(){let list=this.cases.filter(c=>{
      if(c.closed)return false;
      const q=this.search.toLowerCase();if(q&&!`${c.id} ${c.insured} ${c.broker} ${c.line} ${c.stage}`.toLowerCase().includes(q))return false;
      if(this.transaction!=='all'&&c.transaction.toLowerCase()!==this.transaction)return false;
      if(this.bucket==='referral'&&c.bucket!=='referral')return false;
      if(this.bucket==='broker'&&c.bucket!=='broker')return false;
      if(this.bucket==='bind'&&c.bucket!=='bind')return false;
      return true;
    });
      const pri={Urgent:0,High:1,Normal:2,Low:3};
      list.sort((a,b)=>this.sort==='premium'?b.premium-a.premium:this.sort==='due'?a.due.localeCompare(b.due):pri[a.priority]-pri[b.priority]);return list;
    }
    setTenant(name){this.tenant=name;this.cases=this.loadCases();this.rules=this.loadRules();this.events=this.loadEvents();this.selectedId=null;this.route='workbench';}
